            our_t = cheb(nx, ny, rx, ry)
            opp_t = cheb(ox, oy, rx, ry)
            gap = opp_t - our_t
            if gap > best_gap or (gap == best_gap and our_t < best_our_time):
                best_gap = gap
                best_our_time = our_t

        # Encourage finishing quickly; slight bias toward blocking via central approach.
        cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
